SELECT COUNT(*) events,SUM(COALESCE(e.comment,'') REGEXP 'siirr|siirt|yhdist|kopio|jaett|jakami|eriyt|split|merg|mov|cop') destination_comment_matches,SUM(COALESCE(e.comment,'') REGEXP 'siirr|siirt|yhdist|kopio|jaett|jakami|eriyt|split|merg|mov|cop' OR EXISTS(SELECT 1 FROM removals r WHERE r.src=v.src AND r.dst=v.dst AND r.dst_rev=v.dst_rev AND COALESCE(r.comment,'') REGEXP 'siirr|siirt|yhdist|kopio|jaett|jakami|eriyt|split|merg|mov|cop')) either_comment_matches FROM events v LEFT JOIN wtt.edit e ON e.rev_id=v.dst_rev;
